<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Soprano's Catering - Mobile View</title>
    <style>
        :root {
            --primary-orange: #e8b88a;
            --primary-dark: #2c3e50;
            --text-white: #ffffff;
            --text-gray: #f0f0f0;
            --font-script: 'Brush Script MT', cursive; /* Fallback for elegant script */
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            --header-height: 60px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
            -webkit-tap-highlight-color: transparent;
        }

        body {
            font-family: var(--font-sans);
            background-color: #f4f4f4;
            color: var(--text-white);
            overflow-x: hidden;
            line-height: 1.6;
        }

        /* --- Header / Sticky Element --- */
        header {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: var(--header-height);
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 0 20px;
            z-index: 1000;
            /* Transparent background to blend with hero image initially */
            background: rgba(255, 255, 255, 0.05); 
            backdrop-filter: blur(2px);
            transition: background 0.3s ease;
        }

        .logo {
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-decoration: none;
            color: white;
        }

        .logo-text-main {
            font-family: 'Brush Script MT', cursive;
            font-size: 28px;
            font-weight: bold;
            line-height: 1;
        }

        .logo-text-sub {
            font-size: 12px;
            letter-spacing: 2px;
            text-transform: uppercase;
            font-weight: 600;
            opacity: 0.9;
        }

        .menu-toggle {
            background: none;
            border: none;
            cursor: pointer;
            padding: 5px;
            display: flex;
            flex-direction: column;
            gap: 4px;
        }

        .hamburger-line {
            width: 24px;
            height: 2px;
            background-color: white;
            transition: all 0.3s ease;
        }

        /* --- Hero Section (Menu Style) --- */
        .hero {
            position: relative;
            height: 100vh;
            min-height: 700px; /* Ensure enough scroll room for mobile feel */
            width: 100%;
            background-image: url('https://images.unsplash.com/photo-1493770348161-369560ae357d?ixlib=rb-1.2.1&auto=format&fit=crop&w=1350&q=80');
            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            padding: 20px;

            /* Overlay for readability */
            background-blend-mode: overlay;
            background-color: rgba(44, 62, 80, 0.4); 
        }

        .hero-content {
            max-width: 90%;
            animation: fadeInUp 1s ease-out forwards;
            opacity: 0;
            transform: translateY(20px);
        }

        @keyframes fadeInUp {
            to { opacity: 1; transform: translateY(0); }
        }

        .welcome-text {
            font-family: 'Brush Script MT', cursive;
            font-size: 32px;
            color: var(--primary-orange);
            margin-bottom: 10px;
            display: block;
        }

        h1 {
            font-size: 32px;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 15px;
            font-weight: 800;
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        .divider {
            width: 100px;
            height: 2px;
            background-color: var(--primary-orange);
            margin: 0 auto 25px auto;
            opacity: 0.8;
        }

        p.hero-description {
            font-size: 15px;
            line-height: 1.6;
            margin-bottom: 30px;
            font-weight: 300;
            max-width: 500px;
            margin-left: auto;
            margin-right: auto;
            text-shadow: 0 1px 2px rgba(0,0,0,0.5);
        }

        /* --- CTAs & Touch Design --- */
        .cta-btn {
            display: block;
            width: 90%; /* Touch target friendly width */
            max-width: 320px;
            margin: 0 auto 30px auto;
            padding: 18px 20px;
            background-color: var(--primary-orange);
            color: white;
            text-decoration: none;
            border-radius: 50px; /* Pill shape */
            font-size: 16px;
            font-weight: 600;
            text-align: center;
            box-shadow: 0 4px 15px rgba(0,0,0,0.2);
            transition: transform 0.2s ease, box-shadow 0.2s ease;
            /* Prevent text selection on double tap */
            user-select: none; 
            -webkit-user-select: none;
        }

        .cta-btn:active {
            transform: scale(0.98);
            box-shadow: 0 2px 8px rgba(0,0,0,0.2);
            background-color: #d9a57a;
        }

        /* Click-to-call specific styling */
        .click-to-call {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            color: white;
            text-decoration: none;
            font-size: 20px;
            font-weight: 700;
            letter-spacing: 1px;
            margin-bottom: 35px;
            /* Large touch area */
            padding: 10px 20px; 
            border-radius: 8px;
            transition: background 0.2s;
        }

        .click-to-call:hover {
            background-color: rgba(255,255,255,0.1);
        }

        .phone-icon {
            font-size: 22px;
        }

        /* Social Icons */
        .social-icons {
            display: flex;
            gap: 15px;
            justify-content: center;
        }

        .social-link {
            width: 44px; /* Standard touch size */
            height: 44px;
            border: 1px solid rgba(255,255,255,0.6);
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
            color: white;
            text-decoration: none;
            font-size: 20px;
            transition: all 0.2s;
        }

        .social-link:active {
            background-color: white;
            color: var(--primary-dark);
            transform: scale(0.95);
        }

        /* --- Specials Section --- */
        .specials-section {
            position: relative;
            background-color: #34495e;
            padding: 40px 20px 60px 20px;
            text-align: center;
            overflow: hidden;
        }

        /* Decorative wave pattern simulation via CSS gradient/pseudo-element */
        .specials-section::before {
            content: "";
            position: absolute;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-image: repeating-linear-gradient(
                45deg,
                transparent,
                transparent 10px,
                rgba(255,255,255,0.03) 10px,
                rgba(255,255,255,0.03) 20px
            );
            z-index: 0;
            pointer-events: none;
        }

        .specials-title {
            position: relative;
            z-index: 1;
            font-size: 26px;
            text-transform: uppercase;
            letter-spacing: 2px;
            margin-bottom: 30px;
            font-weight: 800;
        }

        .specials-placeholder-btn {
            position: relative;
            z-index: 1;
            width: 140px;
            height: 50px;
            background-color: var(--primary-orange);
            border-radius: 25px;
            margin: 0 auto;
            /* Just a visual placeholder as seen in screenshot cut-off */
        }

        /* Utility for Icons (using simple unicode or CSS shapes if SVG not available, but using text chars here for simplicity in single file) */
        .icon-fb::after { content: "f"; font-family: serif; font-weight: bold; font-style: italic; }
        .icon-ig::after { content: "📷"; font-style: normal; } 

    </style>
</head>
<body>

    <!-- Sticky Header -->
    <header>
        <a href="#" class="logo">
            <span class="logo-text-main">Soprano's</span>
            <span class="logo-text-sub">Catering</span>
        </a>
        <button class="menu-toggle" aria-label="Toggle Menu">
            <span class="hamburger-line"></span>
            <span class="hamburger-line"></span>
            <span class="hamburger-line"></span>
        </button>
    </header>

    <!-- Main Hero Content -->
    <main class="hero">
        <div class="hero-content">
            <span class="welcome-text">Welcome to</span>
            <h1>Soprano's Catering</h1>
            <div class="divider"></div>

            <p class="hero-description">
                From hand-picking our own produce directly from Eastern Market, to making our own salad dressing, Soprano's does everything the old world way! At Soprano's we guarantee you will love our excellent food, professional service, and competitive prices.
            </p>

            <!-- Primary CTA -->
            <a href="#contact" class="cta-btn">Contact Us</a>

            <!-- Click-to-Call CTA -->
            <a href="tel:18009322837" class="click-to-call">
                <span class="phone-icon">&#9742;</span> <!-- Phone Icon Unicode -->
                1 (800) WE-CATER
            </a>

            <!-- Social Links -->
            <div class="social-icons">
                <a href="#" class="social-link icon-fb" aria-label="Facebook"></a>
                <a href="#" class="social-link icon-ig" aria-label="Instagram"></a>
            </div>
        </div>
    </main>

    <!-- Specials Section -->
    <section class="specials-section">
        <h2 class="specials-title">New Winter Specials</h2>
        <div class="specials-placeholder-btn"></div> <!-- Visual placeholder for cut-off button -->
    </section>

</body>
</html>
```
